CREATE TABLE IF NOT EXISTS tally_company_maps (map_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, tally_company TEXT NOT NULL, tally_company_guid TEXT, tally_host TEXT, tally_port INTEGER DEFAULT 9000, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id));
CREATE TABLE IF NOT EXISTS tally_ledger_maps (map_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT, source_key TEXT NOT NULL, tally_ledger TEXT NOT NULL, tally_group TEXT, tax_type TEXT, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,source_key,entity_id));
CREATE TABLE IF NOT EXISTS tally_sync_queue (sync_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, posting_id TEXT NOT NULL, tally_company TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'QUEUED', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, queued_by TEXT NOT NULL, queued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, processed_at TIMESTAMP, UNIQUE(posting_id));
CREATE TABLE IF NOT EXISTS tally_sync_events (event_id TEXT PRIMARY KEY, sync_id TEXT NOT NULL, event_type TEXT NOT NULL, status TEXT NOT NULL, message TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
